package com.htttdn.crm.controller;
import com.htttdn.crm.entity.Feedback; import com.htttdn.crm.repository.FeedbackRepository; import com.htttdn.crm.dto.admin.AdminDtos.FeedbackRequest; import org.springframework.data.domain.Page; import org.springframework.web.bind.annotation.*; import java.time.Instant;
@RestController @RequestMapping("/api/admin/feedback") public class AdminFeedbackController extends AdminPageSupport { private final FeedbackRepository feedback; public AdminFeedbackController(FeedbackRepository feedback){this.feedback=feedback;}
 @GetMapping public Page<Feedback> list(@RequestParam(required=false)String status,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return status==null?feedback.findAll(page(page,size)):feedback.findByStatus(status,page(page,size));}
 @PatchMapping("/{id}") public Feedback update(@PathVariable Long id,@RequestBody FeedbackRequest r){Feedback item=feedback.findById(id).orElseThrow();if(r.status()!=null)item.setStatus(r.status());if(r.adminResponse()!=null)item.setAdminResponse(r.adminResponse());item.setProcessedAt(Instant.now());return feedback.save(item);} }
